#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Apply the opt-in range-diff mapping candidate after phase 1."""
import argparse
from pathlib import Path

PATH = Path("crates/victory-hle/src/modules/xmem.rs")
REPLACEMENTS = (
    ("    // Until the pages are mapped again:",
     "    // For valid, aligned requests preserve complete unchanged spans.\n    // Unknown pages keep the original failure behavior.\n    if diff_mapping() && !pages.is_null() && n != 0 && base % PAGE == 0\n        && n.checked_mul(PAGE).and_then(|bytes| base.checked_add(bytes)).is_some()\n    {\n        // SAFETY: same caller contract as the original mapping path.\n        let requested = unsafe { std::slice::from_raw_parts(pages, n) };\n        if let Some(wanted) = requested.iter().map(|p| physical.pages.get(p).cloned()).collect::<Option<Vec<_>>>() {\n            let _changing = victory_gpu::title_memory_remapping();\n            let (ok, unchanged) = apply_diff(&mut physical, base, &wanted);\n            drop(physical);\n            for (at, bytes) in unchanged {\n                victory_gpu::title_memory_written(at, bytes, true);\n            }\n            return if ok { address } else { std::ptr::null_mut() };\n        }\n    }\n    // Until the pages are mapped again:"),
    ("    let ok = if alias_runs() { alias_in_runs(&mut physical, to, from, len) } else { alias_pages(&mut physical, to, from, len) };",
     "    // Snapshot source slices before modifying the destination. Only use\n    // this path for disjoint, complete ranges; overlapping and missing\n    // source mappings retain the existing behavior.\n    if diff_mapping() && from != 0 && len != 0 && len % PAGE == 0\n        && from % PAGE == 0 && to % PAGE == 0\n        && from.checked_add(len).is_some() && to.checked_add(len).is_some()\n        && (from + len <= to || to + len <= from)\n    {\n        if let Some(wanted) = (0..len).step_by(PAGE)\n            .map(|k| shown_slice(&physical, from + k)).collect::<Option<Vec<_>>>()\n        {\n            let (ok, unchanged) = apply_diff(&mut physical, to, &wanted);\n            let same = unchanged.iter().map(|(_, bytes)| bytes / PAGE).sum::<usize>();\n            drop(physical);\n            for (at, bytes) in unchanged {\n                victory_gpu::title_memory_written(at, bytes, true);\n            }\n            alias_line([1, wanted.len() as u64, same as u64, 0, started.elapsed().as_micros() as u64]);\n            return ok;\n        }\n    }\n    let ok = if alias_runs() { alias_in_runs(&mut physical, to, from, len) } else { alias_pages(&mut physical, to, from, len) };"),
    ("fn alias_runs() -> bool {",
     "fn diff_mapping() -> bool {\n    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();\n    *ON.get_or_init(|| std::env::var_os(\"VICTORY_MAP_DIFF\").is_some_and(|v| v == \"1\"))\n}\n\n// The caller holds both mapping locks. Split into contiguous unchanged\n// and changed spans. Only changed spans reach host map/unmap. Preserve\n// original page-by-page host mapping for changed spans to avoid relying\n// on Wine placeholder coalescing. A view crossing a changed span may\n// still be reconstructed by unmap(), as in the original implementation.\nfn apply_diff(physical: &mut Physical, base: usize, wanted: &[Slice]) -> (bool, Vec<(usize, usize)>) {\n    let same: Vec<bool> = wanted.iter().enumerate().map(|(i, want)| {\n        shown_slice(physical, base + i * PAGE).is_some_and(|have| same_slice(&have, want))\n    }).collect();\n    let mut unchanged = Vec::new();\n    let mut i = 0;\n    let mut mapped = 0;\n    let mut saved = 0;\n    while i < wanted.len() {\n        let mut end = i + 1;\n        while end < wanted.len() && same[end] == same[i] {\n            end += 1;\n        }\n        let at = base + i * PAGE;\n        let bytes = (end - i) * PAGE;\n        if same[i] {\n            unchanged.push((at, bytes));\n            saved += end - i;\n        } else {\n            unmap(physical, at, bytes);\n            for k in i..end {\n                if !map(physical, base + k * PAGE, PAGE, wanted[k].clone()) {\n                    diff_counts(saved, mapped, 0);\n                    return (false, unchanged);\n                }\n                mapped += 1;\n            }\n        }\n        i = end;\n    }\n    diff_counts(saved, mapped, 0);\n    (true, unchanged)\n}\n\n// Cumulative counters; log only occasionally so measurement does not\n// create a new hot path. Values count requested pages, not syscalls.\nfn diff_counts(saved: usize, mapped: usize, scatter: usize) {\n    use std::sync::atomic::AtomicU64;\n    static CALLS: AtomicU64 = AtomicU64::new(0);\n    static SAVED: AtomicU64 = AtomicU64::new(0);\n    static MAPPED: AtomicU64 = AtomicU64::new(0);\n    static SCATTER: AtomicU64 = AtomicU64::new(0);\n    SAVED.fetch_add(saved as u64, Ordering::Relaxed);\n    MAPPED.fetch_add(mapped as u64, Ordering::Relaxed);\n    SCATTER.fetch_add(scatter as u64, Ordering::Relaxed);\n    let calls = CALLS.fetch_add(1, Ordering::Relaxed) + 1;\n    if calls.is_power_of_two() {\n        tracing::info!(\n            calls, saved = SAVED.load(Ordering::Relaxed),\n            mapped = MAPPED.load(Ordering::Relaxed),\n            scatter = SCATTER.load(Ordering::Relaxed),\n            \"mapping diff totals\"\n        );\n    }\n}\n\nfn alias_runs() -> bool {"),
    ("    for i in 0..n {\n        // SAFETY: the title passes `n` addresses and, unless null, `n` pages.",
     "    let mut i = 0;\n    while i < n {\n        // Group only already-identical, consecutive scatter requests.\n        // A failed precheck executes the original single-page request,\n        // preserving order, duplicate-address behavior and failure rules.\n        if diff_mapping() && !pages.is_null() {\n            // SAFETY: same array contract as the original scatter loop.\n            let first = unsafe { *addresses.add(i) } as usize;\n            let count = (n - i).min(256);\n            if first % PAGE == 0 && first.checked_add(count * PAGE).is_some() {\n                let mut physical = physical();\n                let mut matched = 0;\n                while matched < count {\n                    let at = first + matched * PAGE;\n                    let (address, page) = unsafe { (*addresses.add(i + matched) as usize, *pages.add(i + matched)) };\n                    if address != at || page == 0 || !physical.pages.get(&page).is_some_and(|want| {\n                        shown_slice(&physical, at).is_some_and(|have| same_slice(&have, want))\n                    }) {\n                        break;\n                    }\n                    matched += 1;\n                }\n                if matched != 0 {\n                    let _changing = victory_gpu::title_memory_remapping();\n                    drop(physical);\n                    victory_gpu::title_memory_written(first, matched * PAGE, true);\n                    diff_counts(matched, 0, matched);\n                    i += matched;\n                    continue;\n                }\n            }\n        }\n        // SAFETY: the title passes `n` addresses and, unless null, `n` pages."),
    ("        if XMemMapPhysicalPages(address, 1, page).is_null() {\n            return 0;\n        }\n    }\n    1\n}",
     "        if XMemMapPhysicalPages(address, 1, page).is_null() {\n            return 0;\n        }\n        i += 1;\n    }\n    1\n}"),
    ("        // Each page a placeholder of its own (harmless where it is one, or",
     "        // First try coalescing already-exact adjacent placeholders. This\n        // avoids a syscall per page when the host already split them.\n        // Failure leaves the established split-and-coalesce fallback.\n        if diff_mapping() && unsafe {\n            VirtualFree(base as *mut c_void, pages * PAGE, MEM_RELEASE | MEM_COALESCE_PLACEHOLDERS) != 0\n        } {\n            alias_line([0, 0, 0, 1, 0]);\n            return map(physical, base, pages * PAGE, slice.clone());\n        }\n        // Each page a placeholder of its own (harmless where it is one, or"),
    ("        // The same page at a second address shows the same bytes.",
     "        // Change only the middle page and then restore it. Neighbors must\n        // retain their bytes and the changed page must remain a true alias.\n        unsafe {\n            at(a, 0).cast::<u8>().write(11);\n            at(a, 1).cast::<u8>().write(22);\n            at(a, 2).cast::<u8>().write(33);\n        }\n        let changed = [pages[0], pages[2], pages[2]];\n        assert_eq!(XMemMapPhysicalPages(a, 3, changed.as_ptr()), a);\n        unsafe {\n            assert_eq!(at(a, 0).cast::<u8>().read(), 11);\n            assert_eq!(at(a, 1).cast::<u8>().read(), 33);\n            at(a, 1).cast::<u8>().write(44);\n            assert_eq!(at(a, 2).cast::<u8>().read(), 44);\n        }\n        assert_eq!(XMemMapPhysicalPages(a, 3, pages.as_ptr()), a);\n        assert_eq!(unsafe { at(a, 1).cast::<u8>().read() }, 22);\n        let consecutive = [a, at(a, 1), at(a, 2)];\n        assert_eq!(XMemMapPhysicalPagesScatter(consecutive.as_ptr(), 3, pages.as_ptr()), 1);\n        let duplicate = [at(a, 1), at(a, 1)];\n        let changes = [pages[2], pages[1]];\n        assert_eq!(XMemMapPhysicalPagesScatter(duplicate.as_ptr(), 2, changes.as_ptr()), 1);\n        assert_eq!(unsafe { at(a, 1).cast::<u8>().read() }, 22);\n\n        // The same page at a second address shows the same bytes."),
)

def transform(source):
    for old, new in REPLACEMENTS:
        if source.count(old) != 1:
            raise ValueError("Expected exactly one pinned source anchor: " + old[:80])
        source = source.replace(old, new, 1)
    return source

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path)
    args = parser.parse_args()
    path = args.checkout / PATH
    try:
        path.write_text(transform(path.read_text(encoding="utf-8")), encoding="utf-8")
    except (OSError, ValueError) as exc:
        parser.exit(1, f"Mapping diff preparation failed: {exc}\n")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
